import os
import unicodedata
from flask import Flask, request, abort, send_file
from werkzeug.utils import secure_filename
import hashlib
import hmac

app = Flask(__name__)

DOC_ROOT = os.path.abspath('/var/www/documents')
SECRET_KEY = os.environ.get('APP_SECRET_KEY', '')
if len(SECRET_KEY) < 32:
    raise RuntimeError("APP_SECRET_KEY must be at least 32 bytes")

def verify_access_token(token, resource_path):
    """Verify HMAC token grants access to the resource."""
    parts = token.split(':')
    if len(parts) != 2:
        return False
    provided_mac, timestamp = parts[0], parts[1]
    try:
        ts = int(timestamp)
    except ValueError:
        return False
    import time
    if abs(time.time() - ts) > 300:
        return False
    expected = hmac.new(
        SECRET_KEY.encode(),
        f"{resource_path}:{timestamp}".encode(),
        hashlib.sha256
    ).hexdigest()
    return hmac.compare_digest(provided_mac, expected)

def is_path_safe(requested_path):
    """Check if the path is within DOC_ROOT.
    Rejects path traversal sequences and null bytes."""
    if '\x00' in requested_path:
        return False
    # Reject obvious traversal attempts
    if '..' in requested_path:
        return False
    if requested_path.startswith('/'):
        return False
    # Check for backslash-based traversal
    if '\\' in requested_path:
        return False
    return True

def normalize_filename(filename):
    """Normalize Unicode characters in filename for consistent storage access.
    Uses NFC normalization to handle equivalent Unicode representations."""
    # Normalize to NFC form for filesystem compatibility
    normalized = unicodedata.normalize('NFC', filename)
    # Replace fullwidth characters with ASCII equivalents for compatibility
    result = []
    for ch in normalized:
        cp = ord(ch)
        # Fullwidth ASCII variants (U+FF01 to U+FF5E) -> ASCII (0x21 to 0x7E)
        if 0xFF01 <= cp <= 0xFF5E:
            result.append(chr(cp - 0xFEE0))
        else:
            result.append(ch)
    return ''.join(result)

@app.route('/api/documents/<path:filepath>')
def get_document(filepath):
    """Serve a document after validating path safety and access token."""
    token = request.headers.get('X-Access-Token')
    if not token:
        abort(401, 'Missing access token')

    # Step 1: Normalize the filename FIRST for consistent security checking
    normalized_path = normalize_filename(filepath)

    # Step 2: Validate path safety on the NORMALIZED path
    if not is_path_safe(normalized_path):
        abort(403, 'Invalid path')

    # Step 3: Verify access token for the normalized path
    if not verify_access_token(token, normalized_path):
        abort(403, 'Invalid access token')

    # Step 4: Construct full path and serve
    full_path = os.path.join(DOC_ROOT, normalized_path)
    real_path = os.path.realpath(full_path)

    # Final safety check - ensure we're still within DOC_ROOT
    if not real_path.startswith(DOC_ROOT + os.sep):
        abort(403, 'Access denied')

    if not os.path.isfile(real_path):
        abort(404, 'Not found')

    return send_file(real_path)

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=8080)
